      "赤穗熊骑": "Cavalier Ours de Gerbe Rouge",
      "麦田稻草魔像": "Golem de Paille du Champ de Blé",
      "留守的农民夫妇": "Le Couple de Fermiers qui Sont Restés",
      "别紧张，年轻人。那些熊没有杀害这里的人。它们来到农场后，只把原来的村民赶去了王城方向。": "Allons, jeune. Ces ours n'ont tué personne ici. Quand ils sont venus à la ferme, ils ont seulement chassé les villageois vers la capitale royale.",
      "我们留下，是因为没有从它们身上感到敌意。最初它们连犁怎么扶都不知道，只会用蛮力把田翻得乱七八糟。": "Nous sommes restés parce que nous n'avons jamais senti d'hostilité de leur part. Au début, ils ne savaient même pas comment tenir une charrue — ils ont juste dévasté les champs par la force brute.",
      "后来我们教熊男修水渠、播麦种，也教熊娘照料蜂箱和收割。它们学得很慢，但从不糟蹋粮食。": "Plus tard, nous avons appris aux hommes-ours à réparer les canaux et semer du blé, et aux femmes-ours à soigner les ruches et rapporter la moisson. Ils apprennent lentement, mais ils ne gaspillent jamais de nourriture.",
      "它们会在谷仓里给幼熊留出最暖的位置，也会把第一袋新麦送到我们门口。至少在我们眼里，它们没有传闻中那么可恶。": "Ils réservent la place la plus chaude de la grange pour leurs petits, et ils apportent le premier sac de nouveau blé à notre porte. Du moins à nos yeux, ils ne sont pas aussi vils que les rumeurs le disent.",
      "若你一定要继续往前，就亲眼看看再作判断吧。这里发生的事，也许并不是简单的怪物占领村庄。": "Si vous devez continuer, voyez-le de vos propres yeux avant de juger. Ce qui s'est passé ici n'est peut-être pas un simple cas de monstres saisissant un village.",
