      "夜校、公共图书馆与向异族开放的考试": "Écoles nocturnes, bibliothèques publiques et examens ouverts à d'autres races",
      "公路网、驿站通行权与牧道协定": "Réseaux routiers, droits de passage des stations relais et accords de voies de troupeaux",
