      "沙幕王庭": "Cour du Voile de Sable",
      "让王族先承担风险，再接受欢呼": "Que les royaux portent le risque en premier, puis acceptent les applaudissements",
      "白狼族": "Clan du Loup Blanc",
      "合法军籍、家属安置与面向兽族的城市教育": "Enrôlement légal, réinstallation familiale et éducation urbaine pour les gens-bêtes",
      "不灭凰族": "Phénix Immortels",
      "火灾救援、灾后重建与对重生者的身份登记": "Sauvetage incendie, reconstruction après sinistre et enregistrement d'identité pour les renaissants",
      "黑锋骑士团": "Ordre de l'Arête Noire",
      "让锋刃只指向准备好应战的人": "Que la lame pointe seulement vers ceux prêts à combattre",
      "蒲公英花灵": "Fées du Pissenlit",
      "市集、印刷术与允许异族登台的演出许可": "Marchés, impression et licences de performance qui permettent à d'autres races de monter sur scène",
      "血斧角斗场": "Arène de la Hache Sanglante",
      "裁判最好离远点，我的胜利通常会溅到前三排": "L'arbitre devrait reculer—mes victoires éclaboussent généralement les trois premières rangées",
      "晶辉学院": "Académie de l'Éclat Cristallin",
      "用晶体测量魔力，让法术可以被复现": "Mesurer la magie avec des cristaux pour que les sorts puissent être reproduits",
      "鹿角兽人": "Gens-bêtes aux Bois",
      "护林法、共享牧道与边地自治议会": "Lois de protection des forêts, voies de troupeaux partagées et conseils d'auto-gouvernance frontalière",
      "机巧侏儒": "Gnomes Mécaniques",
      "专利制度、公开船坞与事故追责": "Systèmes de brevets, chantiers navals ouverts et responsabilité pour les accidents",
      "虚空观测站": "Observatoire du Vide",
      "用长期观测区分天启、幻觉和噪声": "Observation à long terme pour distinguer la révélation de l'illusion et du bruit",
      "黄金狮鹫族": "Griffons Dorés",
      "空骑军籍、兽族居住权与救援航线": "Enrôlement des chevaucheurs de ciel, résidence des gens-bêtes et routes de vol de sauvetage",
      "我加入王国不是为了变成人类，而是因为这里允许我保留自己，也允许我凭本事向前。": "Je n'ai pas rejoint le royaume pour devenir humain, mais parce qu'ici je peux rester moi-même et avancer selon mon mérite.",
      "血统只决定出生，制度和选择才决定我们能否并肩站在这里。": "La lignée décide seulement où nous naissons; les institutions et les choix décident si nous pouvons nous tenir côte à côte ici.",
      "今天我代表的不是归顺，而是一个异族也能公开竞争、堂堂正正赢得掌声的王国。": "Aujourd'hui, je ne représente pas la soumission, mais un royaume où d'autres races peuvent concourir ouvertement et gagner les applaudissements honnêtement.",
      "漂亮。能把我逼到这里，说明王都接纳的也确实是一位值得尊敬的对手。": "Magnifique. Me pousser si loin prouve que la capitale accueille vraiment un adversaire digne de respect.",
      "我不会替那些偏见证明异族只配躲在荒野。来，最后一轮！": "Je ne prouverai pas ces préjugés qui disent que d'autres races doivent rester cachées dans les terres sauvages. Allez—dernier round!",
      "你赢了。愿这座竞技场继续证明：人类与异族可以争胜，却不必彼此仇恨。": "Tu gagnes. Que cette arène continue de le prouver: les humains et d'autres races peuvent concourir sans se haïr.",
      "出牌再快一点。观众买票不是来看你思考人生的。": "Joue plus vite. Le public n'a pas acheté de billets pour te regarder te poser des questions existentielles.",
      "你管这叫战线？我家的晾衣绳都比它更难突破。": "Tu appelles ça une ligne de bataille? Ma corde à linge est plus difficile à franchir.",
      "放心，我会给你留点体面——至少等裁判宣布以后再笑。": "Détends-toi, je vais te laisser un peu de dignité—j'attendrai au moins l'appel de l'arbitre avant de rire.",
      "别看记分牌了，它不会因为你盯得够久就站到你那边。": "Arrête de regarder le tableau de bord. Il ne changera pas de côté juste parce que tu le regardes longtemps.",
      "刚才那一下还算像样。不过想让我闭嘴，你还差最后一段路。": "Ce dernier coup était décent. Mais pour me faire taire, tu dois encore aller jusqu'au bout.",
      "别急着向观众挥手！我只是把翻盘留到最吵的时候。": "Ne fais pas de signes à la foule! Je garde simplement mon retour pour quand ce sera le plus bruyant.",
      "今天算你赢。下次我会先击败你，再投诉这块明显偏向你的地板。": "Tu gagnes aujourd'hui. La prochaine fois, je te battrai en premier, puis je déposerai plainte contre ce sol qui te favorise clairement.",
      "别介意，我正在记录你的出牌习惯。真正危险的数据，往往来自自信的人。": "Ne m'en veux pas, j'enregistre tes habitudes de jeu. Les données vraiment dangereuses viennent souvent de gens confiants.",
      "每次交换都在缩小答案范围。再过几轮，你的选择就会只剩一种。": "Chaque échange réduit la réponse. Quelques rounds de plus et il ne te restera qu'un seul choix.",
      "竞技场比实验室诚实：错误的理论会当场掉血。": "L'arène est plus honnête que le laboratoire: les mauvaises théories perdent de la Vie sur le coup.",
      "放心，若你击败我，我会如实把结论写进报告。": "Sois assuré que si tu me bats, j'écrirai la conclusion dans mon rapport fidèlement.",
      "数据偏离预测了。很好，没有意外的研究才最无聊。": "Les données s'écartent de la prédiction. Bien—la recherche sans surprises est la plus ennuyeuse.",
      "样本正在反过来验证研究者……我承认这个结果很有说服力。": "L'échantillon vérifie maintenant le chercheur... J'avoue que ce résultat est très convaincant.",
      "结论成立：你的临场判断胜过我的模型。下一版论文会写上这一条。": "Conclusion confirmée: ton jugement sur le moment bat mon modèle. Le prochain brouillon de mon article le dira.",
      "竞技场没有真正的仇敌，只有愿意把本领摆到阳光下的人。": "Il n'y a pas de vrais ennemis dans l'arène, seulement des gens disposés à montrer leurs compétences à la lumière du jour.",
      "别为保存生命而放弃阵线。荣誉来自承担风险，不是躲过风险。": "N'abandonne pas la ligne pour sauver ta vie. L'honneur vient de prendre des risques, pas de les éviter.",
      "观众记得胜负，战士应当记得自己在压力下做过什么选择。": "Le public se souvient du résultat; un guerrier devrait se souvenir des choix faits sous pression.",
      "无需留手。尊重对手最好的方式，就是拿出真正想赢的力量。": "Ne te retiens pas. La meilleure façon de respecter un adversaire est de montrer la force qui veut vraiment gagner.",
      "好一记正面突破。疼痛会过去，失去判断才是真正的败势。": "Une belle percée frontale. La douleur passe; perdre ton jugement est la véritable défaite.",
      "只剩最后一点生命，正好用来检验最后一点意志。": "Un dernier point de Vie—parfait pour tester le dernier vestige de volonté.",
      "胜负已定。我记住了你的战术，也会把掌声留给配得上它的人。": "Le match est décidé. J'ai mémorisé tes tactiques, et je réserverai mes applaudissements à ceux qui les méritent.",
      "并": "et",
