      "击败第一关第一个Boss，取得女王血河水后，才能进入最终试炼。": "Vaincez le premier boss du Chapitre 1 et obtenez l'eau fluviale du sang de la reine pour entrer dans l'épreuve finale.",
      "海港城市 · 老兵训练场": "Cité du Port · Terrain d'Entraînement des Vétérans",
      "归乡之战幸存者的七堂课": "Sept Leçons des Survivants de la Guerre du Retour",
      "每关首次通关永久增加1点最大法力；没有碎片，也没有总上限。重复挑战不会重复获得法力。": "Le premier accomplissement de chaque épreuve ajoute définitivement 1 Mana Max ; pas de fragments et pas de plafond global. Les accomplissements répétés n'accordent pas à nouveau mana.",
