      "64名英雄使用相同卡池展开六轮淘汰赛，对手卡牌等级每场随机。": "64 héros partagent le même bassin de cartes dans une élimination directe à six manches ; les niveaux des cartes des adversaires sont aléatoires à chaque match.",
      "王冠杯 · 64强": "Coupe de la Couronne · Top 64",
      "晋级奖金：32强100金币、16强200、8强400、4强800、亚军1200、冠军1600。": "Prix d'avancement : Top 32 100 or, Top 16 200, Top 8 400, Top 4 800, Finaliste 1200, Champion 1600.",
