      "已加入英雄技能收藏，可在英雄档案装备。": "Ajouté à votre collection de compétences de héros ; équipez-le dans le Profil du Héros.",
      "，你成为本届王冠杯冠军！": ", vous êtes le Champion de la Coupe de la Couronne de cette année !",
