      "英雄、收藏、卡组与所有永久成长都会被删除。此操作无法撤销。": "Votre héros, votre collection, votre deck et toute la croissance permanente seront supprimés. Cela ne peut pas être annulé.",
      "我理解，继续": "Je comprends, continuer",
