      "恢复生命": "Restaurer la Santé",
      "+100金币": "+100 or",
      "+20经验": "+20 XP",
      "直接胜利": "Victoire instantanée",
      "直达Boss": "Sauter au Boss",
      "抽1张牌": "Piocher 1 carte",
      "战斗法力+1": "Mana de bataille +1",
      "退出当前关卡？": "Quitter le chapitre actuel ?",
      "已击败的节点、路线解锁和本轮奖励都会保留。之后点击“继续游戏”即可从当前进度继续。": "Les nœuds vaincus, les itinéraires déverrouillés et les récompenses de cette course sont tous conservés. Cliquez sur « Continuer » plus tard pour reprendre à partir de votre progression actuelle.",
      "保存并退出": "Enregistrer et Quitter",
      "第五关存档调整": "Ajustement de la Sauvegarde du Chapitre 5",
      "只留下最终首领？": "Laisser seulement le boss final ?",
      "将第五关设置为前19个首领已经击败，只留下银灰狼女猎手。英雄、金币、收藏、卡组以及其他关卡存档均不会改变。": "Définit le Chapitre 5 de sorte que les 19 premiers boss sont vaincus, ne laissant que la Chasseuse Louve Gris-Argent. Votre héros, votre or, votre collection, votre deck et d'autres sauvegardes de chapitre ne changeront pas.",
      "确认调整": "Confirmer",
      "存档已删除并重建。": "Sauvegarde supprimée et reconstruite.",
      "第五关已调整：前19个首领已击败，只剩最终首领。": "Chapitre 5 ajusté : les 19 premiers boss sont vaincus ; seul le boss final reste.",
