      "王都竞技场 · {0}": "Arène Royale · {0}",
      "{0}使用与你完全相同的卡组，但卡牌等级在本场随机决定。": "{0} utilise exactement le même deck que vous, mais les niveaux de cartes sont aléatoires pour ce match.",
      "遭遇{0}「{1}」。击穿任意一路即可攻击敌方英雄。": "Vous avez rencontré {0} « {1} ». Percez n'importe quelle voie pour attaquer le héros ennemi.",
