      "每回合恢复至 {0}/{1}。永久上限不封顶，只能由统领试炼首次通关提升。": "Se restaure à {0}/{1} chaque tour. Le plafond permanent n'a pas de limite et ne peut être augmenté que par les premières clears des Épreuves du Commandant.",
