      "Lv{0} · {1} · {2}经验{3}": "Lv{0} · {1} · {2} XP{3}",
      "卡组中有{0}张重复卡牌，请保持每张卡只有1张。": "Votre deck a {0} cartes en double; gardez seulement 1 copie de chaque carte.",
      "至少还需加入 {0} 张卡牌。": "Ajoutez au moins {0} cartes supplémentaires.",
