      "重新开始第{0}关？": "Redémarrer le Chapitre {0}?",
      "只会清空第{0}关的节点记录与本关生命状态，其他关卡的独立存档不会受影响。": "Seuls les dossiers de nœud et l'état de Vie du Chapitre {0} seront effacés; les sauvegardes séparées des autres chapitres ne seront pas affectées.",
