      "{0}×{1}": "{0} ×{1}",
      "晨曦照亮战线：随从共恢复{0}点生命，英雄恢复{1}点生命。": "L'aube illumine la ligne : les serviteurs récupèrent {0} PV au total, votre héros {1} PV.",
      "{0}陷入血怒，本回合攻击力提升至{1}，可以立即攻击。": "{0} entre en frénésie : son attaque passe à {1} ce tour et il peut attaquer immédiatement.",
